package replication

import (
	"strings"
	"testing"

	"github.com/marcgauthier/murmur-sql/murmur/internal/postcard"
)

func TestStoredVectors(t *testing.T) {
	m := &Manifest{
		Database: idOf(1), Donor: idOf(3), Recipient: idOf(2), Transfer: idOf(9),
		Expires: 100, Bytes: 70000, Digest: fill32(6), Schema: fill32(5),
		Progress: []Progress{{Origin: idOf(3), Applied: 7, Observed: 7, RetainedFrom: 1, RetainedThrough: 7}},
		Chunks:   [][32]byte{fill32(8), fill32(9)}, Signature: []byte{1, 2, 3},
	}
	checkVector(t, "manifest", Hex(EncodeManifest(m)), "")
	checkVector(t, "incoming", Hex(EncodeIncoming(&Incoming{Manifest: *m, Deadline: 50})), "")
	pin := &Pin{Recipient: idOf(2), Boundary: map[NodeId]uint64{idOf(3): 7}, Expires: 100, Digest: fill32(6)}
	checkVector(t, "pin", Hex(EncodePin(pin)), "0202020202020202020202020202020201030303030303030303030303030303030700640606060606060606060606060606060606060606060606060606060606060606")
	pin.HasTarget = true
	pin.Target = map[NodeId]uint64{idOf(3): 9, idOf(8): 2}
	checkVector(t, "pin_target", Hex(EncodePin(pin)), "02020202020202020202020202020202010303030303030303030303030303030307010203030303030303030303030303030303090808080808080808080808080808080802640606060606060606060606060606060606060606060606060606060606060606")
	signedRef := ""
	checkVector(t, "signed", Hex(m.signedBytes()), strings.TrimPrefix(signedRef, "f401"))

	peer := &PeerRetention{Node: idOf(4), LastSeenMillis: 1000, Retired: true,
		Acknowledged: map[NodeId]uint64{idOf(3): 7}}
	checkVector(t, "peer", Hex(EncodePeerRetention(peer)), "04040404040404040404040404040404e80701010303030303030303030303030303030307")

	h := &Header{SourceDatabase: idOf(1), SourceNode: idOf(3), Stream: "low", Sequence: 4,
		Bundle: idOf(9), Recipient: fill32(5), Ephemeral: fill32(6), Digest: fill32(8)}
	copy(h.Nonce[:], bytesRepeat(7, 24))
	checkVector(t, "header", Hex(EncodeHeader(h)), "")
	h.Origin = &Origin{Node: idOf(3), Sequence: 5, Transaction: idOf(2), Digest: fill32(8)}
	checkVector(t, "header_origin", Hex(EncodeHeader(h)), "")
	checkVector(t, "origin", Hex(encode(func(e *postcard.Encoder) { encodeOrigin(e, h.Origin) })), "0303030303030303030303030303030305020202020202020202020202020202020808080808080808080808080808080808080808080808080808080808080808")
	plain := *h
	plain.Origin = nil
	bundle := &Bundle{Version: 1, Header: plain, Ciphertext: []byte{1, 2}, Signature: []byte{3}}
	checkVector(t, "bundle", Hex(EncodeBundle(bundle)), "")
	fp := &FilePart{Name: "a", Digest: fill32(8), Bytes: 10, Offset: 2, Data: []byte{4, 5}, FinalPart: true}
	checkVector(t, "filepart", Hex(EncodeFilePart(fp)), "016108080808080808080808080808080808080808080808080808080808080808080a0202040501")
	meta := &FileMetadata{Name: "a", Digest: fill32(8), Bytes: 10, Generation: 2, Millis: 100, Node: idOf(2), Deleted: true}
	checkVector(t, "filemeta", Hex(EncodeFileMetadata(meta)), "016108080808080808080808080808080808080808080808080808080808080808080a02640202020202020202020202020202020201")
	checkVector(t, "avail_local", Hex(EncodeFileAvailability(&FileAvailability{Kind: FileLocal})), "00")
	checkVector(t, "avail_remote", Hex(EncodeFileAvailability(&FileAvailability{Kind: FileRemote, Remote: []NodeId{idOf(2)}})), "010102020202020202020202020202020202")
	checkVector(t, "avail_un", Hex(EncodeFileAvailability(&FileAvailability{Kind: FileUnavailable})), "02")
	rot := &FileKeyRotationStatus{CurrentGeneration: 1, OldGenerationObjects: 2, OldGenerationMetadataMissingLocally: 3, StagedTransfers: 4, PreviousKeyUnusedLocally: true}
	checkVector(t, "rot", Hex(EncodeFileKeyRotationStatus(rot)), "0102030401")
	checkVector(t, "u64", Hex(encode(func(e *postcard.Encoder) { e.U64(9) })), "09")
	checkVector(t, "pair", Hex(encode(func(e *postcard.Encoder) { e.U64(2); e.U64(100) })), "0264")
	floor := encode(func(e *postcard.Encoder) {
		d := fill32(8)
		e.Raw(d[:])
		e.U64(7)
		e.U64(9)
		e.Bool(false)
	})
	checkVector(t, "floor", Hex(floor), "0808080808080808080808080808080808080808080808080808080808080808070900")
}
